import{z as s,x as o,o as r,c as p,q as l,j as A,D as a,d as B,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"学习型优化器","description":"","frontmatter":{"title":"学习型优化器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/learned-optimizer.md","filePath":"cs/learned-optimizer.md","lastUpdated":1791063341000}'),d={name:"cs/learned-optimizer.md"};function D(m,E,c,u,h,f){const t=o("Mermaid");return r(),p("div",null,[E[2]||(E[2]=l('<h1 id="学习型优化器" tabindex="-1">学习型优化器 <a class="header-anchor" href="#学习型优化器" aria-label="Permalink to &quot;学习型优化器&quot;">​</a></h1><div class="epigraph"><p>把过去计划的真实延迟与基数当训练信号，下一次搜索用模型代替或修正直方图公式；泛化失败时仍要能退回 Selinger。</p><footer>—— 据 Marcus et al. Neo；Yang et al. 学习基数；Krishnan et al.；传统 Selinger 对照</footer></div><p><a href="/cs/adaptive-query-processing">上一课</a>在单次执行中途纠偏。本课不重做监测点。缺口是跨查询的记忆：相似语句反复出现，自适应每次都付探测税。学习型优化器（learned optimizer）用历史 <code>(查询特征 → 计划, 运行时间)</code> 或学习基数估计，改变 DP 的输入或直接提议树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手工直方图与独立假设是强先验。学习模型（树、神经网络）拟合工作负载，可能在相关列、复杂谓词上更准。缺口是<strong>工作负载漂移</strong>：训练在白天报表，晚上 ETL 分布不同，模型会自信地选错。还有计划空间合法性：模型不能提议外连接左右颠倒的非法树。</p><p>与计算机栏的机器学习课分开：这里模型只服务代价或基数，不是训练 Transformer。特征是表、列、谓词、估计行数，标签是真实行数或延迟。</p><p><span class="marginnote">「基数估计」就是预估查询每一步会返回多少行的手段，它是代价公式的原料。数字实例：直方图估计某过滤条件剩 1000 行、实际有 50 万行，DP 就会偏爱一个看似便宜的嵌套循环连接，运行时间可能从毫秒级拖到分钟级——差 500 倍的行数估计足以让计划彻底选错。</span></p><p><span class="marginnote">初学者容易以为学习型优化器是用神经网络端到端生成整棵计划树。实际上主流做法（如学习基数）只替换 DP 的一个输入——行数估计，计划枚举骨架仍是经典 Selinger，这样合法性和可回退性才有保障。</span></p><p><span class="marginnote">Neo（Marcus et al.）等把计划搜索与学习价值函数结合。学习基数估计有大量后续工作。本课只钉：学习是修正估计或搜索策略，不是取消代数指称。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两条路：① 学习基数，DP 照旧；② 学习代价或策略，引导枚举。必须保留回退：模型不可用时走直方图 + Selinger。训练数据来自 explain analyze、自适应监测、采样。过拟合到某次参数窥视，等于把计划缓存的坏处学成权重。</p><p>解释性：DBA 要能问「为什么选 NLJ」。纯黑盒在回归事故里不可运维——后课计划提示与稳定性。</p>',12)),(r(),A(n,null,{default:a(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HIST%5B%22%E7%9B%B4%E6%96%B9%E5%9B%BE%E5%85%88%E9%AA%8C%22%5D%20--%3E%20MIX%5B%22%E4%B8%8E%E5%AD%A6%E4%B9%A0%E4%BC%B0%E8%AE%A1%E6%B7%B7%E5%90%88%22%5D%0A%20%20LOG%5B%22%E6%89%A7%E8%A1%8C%E5%8F%8D%E9%A6%88%22%5D%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%E5%9F%BA%E6%95%B0%E6%88%96%E4%BB%A3%E4%BB%B7%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20TRAIN%20--%3E%20MIX%0A%20%20MIX%20--%3E%20DP%5B%22DP%20%2F%20%E7%AD%96%E7%95%A5%E6%90%9C%E7%B4%A2%22%5D%0A%20%20DP%20--%3E%20FB%5B%22%E5%90%88%E6%B3%95%E8%AE%A1%E5%88%92%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"冷启动：新表无历史，必须经典统计。缓存：学习计划同样要在模式变更时失效。安全：探索（试试新计划）可能把生产打慢，通常在副本或限流下探索。",-1)),E[5]||(E[5]=e("p",null,"学习估计若系统性低估，灾难与经典误差同类，只是更难用「加桶」修好——要有监控估计/实际比。",-1)),(r(),A(n,null,{default:a(()=>[i(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%96%B0%E6%9F%A5%E8%AF%A2%E5%88%B0%E6%9D%A5%22%5D%20--%3E%20FE%5B%22%E6%8F%90%E5%8F%96%E8%A1%A8%2F%E5%88%97%2F%E8%B0%93%E8%AF%8D%E7%89%B9%E5%BE%81%22%5D%0A%20%20FE%20--%3E%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%E7%BB%99%E5%87%BA%E5%9F%BA%E6%95%B0%E4%B8%8E%E4%BB%A3%E4%BB%B7%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20MODEL%20--%3E%20CHK%7B%22%E4%BC%B0%E8%AE%A1%2F%E5%AE%9E%E9%99%85%E6%AF%94%E5%80%BC%E5%BC%82%E5%B8%B8%EF%BC%9F%22%7D%0A%20%20CHK%20--%20%22%E6%AD%A3%E5%B8%B8%22%20--%3E%20USE%5B%22%E9%87%87%E7%94%A8%E5%AD%A6%E4%B9%A0%E8%AE%A1%E5%88%92%22%5D%0A%20%20CHK%20--%20%22%E6%BC%82%E7%A7%BB%22%20--%3E%20FB%5B%22%E5%9B%9E%E9%80%80%E7%9B%B4%E6%96%B9%E5%9B%BE%20%2B%20Selinger%22%5D%0A%20%20USE%20--%3E%20LOG%5B%22%E8%AE%B0%E5%BD%95%E7%9C%9F%E5%AE%9E%E8%A1%8C%E6%95%B0%E4%BE%9B%E5%86%8D%E8%AE%AD%E7%BB%83%22%5D%0A%20%20FB%20--%3E%20LOG%0A%20%20LOG%20--%3E%20RETRAIN%5B%22%E5%AE%9A%E6%9C%9F%E9%87%8D%E8%AE%AD%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20RETRAIN%20--%3E%20MODEL%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">为什么重要：估计/实际行数比是学习优化器的体温计。如果模型系统性低估 100 倍，它会一直偏爱看似便宜、实际昂贵的计划；经典方法的误差至少还能靠加直方图桶修，模型误差却要靠这条监控回路及时发现并回退。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲索引选择的学习版细节——下一课索引选择与下推仍以经典为主，学习可作辅。也不把自动调参整个 DBMS 当一课。</p><p>后课默认：学习模型是统计模块的插件，指称与事务不变。索引选择课处理「建哪些物理结构」，与「给定结构选哪条路」分开。</p><p>没有反馈回路的「学习」只是一次拟合，会过期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>学习修正基数或搜索，必须合法、可回退、可失效。</li><li>工作负载漂移与不可解释是运维边界。</li><li>索引选择与条件下推下一课：物理设计与改写的交界。</li><li>出处：Marcus et al. Neo；学习基数估计文献；Selinger 对照。</li></ul>',7))])}const C=s(d,[["render",D]]);export{T as __pageData,C as default};
